CREATE TABLE t1(a INTEGER, b INTEGER, c TEXT); WITH RECURSIVE g(i) AS (VALUES(1) UNION ALL SELECT i+1 FROM g WHERE i<50000) INSERT INTO t1(a,b,c) SELECT i,(i*7919+17)%500000,printf('number-%06d',(i*7919+17)%500000) FROM g; CREATE INDEX i1a ON t1(a); CREATE INDEX i1b ON t1(b); CREATE INDEX i1c ON t1(c);